export class APIError extends Error {
  constructor(message, statusCode, response) {
    super(message);
    this.name = 'APIError';
    this.statusCode = statusCode;
    this.response = response;
  }
}

export class AuthenticationError extends APIError {
  constructor(message, response) {
    super(message, 401, response);
    this.name = 'AuthenticationError';
  }
}

export class RateLimitError extends APIError {
  constructor(message, response) {
    super(message, 429, response);
    this.name = 'RateLimitError';
  }
}

export class ValidationError extends APIError {
  constructor(message, response) {
    super(message, 400, response);
    this.name = 'ValidationError';
  }
}

export function handleAPIError(error, response) {
  if (response?.status === 401) {
    throw new AuthenticationError('Invalid or expired API key', response);
  }
  
  if (response?.status === 429) {
    throw new RateLimitError('API rate limit exceeded', response);
  }
  
  if (response?.status === 400) {
    throw new ValidationError('Invalid request parameters', response);
  }
  
  if (response?.status >= 500) {
    throw new APIError(`Server error: ${response.status}`, response.status, response);
  }
  
  throw new APIError(error.message, response?.status, response);
}